create table if not exists public.projects (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, name text not null, data jsonb not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(user_id,name));alter table public.projects enable row level security;create policy "Users read own projects" on public.projects for select to authenticated using ((select auth.uid())=user_id);create policy "Users insert own projects" on public.projects for insert to authenticated with check ((select auth.uid())=user_id);create policy "Users update own projects" on public.projects for update to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id);create policy "Users delete own projects" on public.projects for delete to authenticated using ((select auth.uid())=user_id);